"""Seal the bounded resume report from measured task artifacts only."""
import hashlib,json,subprocess
from pathlib import Path
from collect_resume_fast_ledger import collect,ROOT


def read(path):return json.loads((ROOT/path).read_text(encoding='utf-8-sig'))
def digest(path):
    with path.open('rb') as stream:return hashlib.file_digest(stream,'sha256').hexdigest()


def main():
    rows=collect();cases=read('CASE_RESULTS.json');runtime=read('EXECUTION_ACCOUNTING.json')
    capsule=read('capsule_completion/SEAL.json');assembly=read('capsule_complete_retry/ASSEMBLY.json')
    bent=read('bent_seal18/SEAL.json');repair=read('capsule_completion/repaired_core/REPAIR.json')
    core=read('capsule_completion/repaired_core/HARD_QUALITY.json')
    sections=[]
    def add(title,body):sections.append('### '+title+'\n\n'+body)
    add('A. Authority verification','Initial HEAD: 97336205bf94dd8bea5e4445ad6b0c6e9dc27b70. The sealed incremental-degree report and authority hashes match TASK_MANIFEST.json. Scientific algorithms, frozen gates, wall, first layer, and V3 are unchanged. Some historical raw receipt/node files were unavailable at load time; recovered inputs were accepted only after exact original scientific identity reconstruction. Old result files were not rewritten.')
    add('B. Starting checkpoints','Capsule 12; bent passage 6; interacting ellipsoids 3; four separated regions 2. STARTING_CHECKPOINT_INVENTORY.json binds preserved checkpoint identities. Capsule geometry 10–12 was not regenerated. Bent layer 6 was reconstructed from preserved compact proofs and saved geometry, with exact old quality, Patricia-root, and whole scientific hashes.')
    add('C. Compute policy',f"Conservative scientific-worker wall time: {runtime['seconds']:.6f} s. This includes input recovery, failed attempts, checkpoint I/O, core, and seals. It excludes idle time, coding, tests, and report hashing. Target 7,200 s; hard cap 10,800 s. Target exceeded: {runtime['target_exceeded']}; hard cap exceeded: {runtime['hard_cap_exceeded']}. Accounting lists non-overlapping worker intervals. No completed ordinary layer exceeded 120 s. Bent layer 19 was stopped for no committed progress, preserving layer 18. Periodic external monitoring stopped it 917.724871 s after the last committed record; it did not interrupt the long callback at exactly 900 s.")
    add('D. Capsule continuation','Capsule advanced 12→20: eight new ordinary layers, 65,536 new prisms, no remesh. Final shell: 163,840 prisms; 4,098 wall vertices; 8,192 wall triangles. Every accepted layer passed the unchanged gates.')
    add('E. Capsule final seal',f"Independent global seal passed: {capsule['coverage']['active']:,} relations; missing 0, duplicate 0, forbidden 0, unresolved 0. All 163,840 witness degrees and directions match. Complete quality arrays and incidence match. Seal runtime 622.204845 s. Root: `{capsule['certificate']['root']}`. Durable compact milestone and its manifest bind the full proof population.")
    add('F. Capsule core/complete result',f"BoundedCompleteQualified: {assembly['total_cells']:,} cells = 163,840 prisms + 31,366 tetrahedra. The fixed interface is exact. Standard repair moved {repair['moved']} interior vertices, affected {repair['affected']} cells, and fixed {repair['fixed']} boundary vertices. No connectivity change. Final core minima/maxima: `{json.dumps({'minimum':core['minimum'],'maximum':core['maximum']},sort_keys=True)}`. Complete certificate: {assembly['shell_proofs_reused']:,} reused + {assembly['new_relations']:,} new = {assembly['total_relations']:,}; zero missing/duplicate/forbidden/unresolved. Assembly and exact filling pass. Successful complete-worker runtime 907.271000 s; assembly 859.712948 s; new certification 162.385197 s. Initial interrupted publication is separately charged and preserved.")
    add('G. Bent passage',f"Bent advanced 6→18: twelve new ordinary layers, 98,304 new prisms, no committed remesh. Final retained shell: 147,456 prisms and 12,734,448 certified relations. The independent layer-18 seal passed in {bent['seconds']:.6f} s; full global degree {bent['global_degree']['seconds']:.6f} s. All 147,456 witnesses/directions match. Missing/duplicate/forbidden/unresolved are zero. Root `{bent['certificate']['root']}`; final scientific identity `{bent['scientific']}`. Nominal layer 19 failed with 20 cell-quality, four negative exact-Jacobian, and four interpolation-weight failures; minimum failed determinant 0.000346733763689126 and minimum failed weight 0.05186338964308482. The unchanged general correction path recorded failure counts 48, 79, 34, 29, 29, 27. No replacement committed before the no-progress stop. This does not prove remesh infeasible. End reason: BudgetStoppedStagnant.")
    inter=cases['interacting_features_production'];iseal=inter['seal']
    add('H. Interacting ellipsoids',f"Saved layer 3 authority was recovered exactly, including quality digest and whole legacy scientific identity. One new layer committed: 3→4 in 118.300101 s, adding 24,576 prisms and 1,667,073 relations. The partial shell contains 98,304 prisms and 6,373,493 relations. End reason: {inter['end_reason']}. Independent final seal passed; complete quality arrays and all 98,304 witness/direction results match; missing/duplicate/forbidden/unresolved are zero. Root `{iseal['certificate']['root']}`. Scientific identity `{iseal['scientific']}`. Final milestone restart exact: {inter['restart']}. No core was attempted for this partial shell.")
    add('I. Four separated regions',json.dumps(cases['separated_regions_production'],indent=2))
    add('J. Ordinary-layer performance',(ROOT/'LAYER_TABLES.md').read_text())
    add('K. Degree-validation behavior','Ordinary all-prism commits retain the qualified exact incremental degree path. New witnesses are evaluated; screened historical witnesses retain exact authority. The ledger gives selected/reused counts. Final seals independently run the complete global degree audit. No predicate was removed or approximated.')
    add('L. Continuous-certification behavior','Complete continuous coverage remains mandatory. Capsule new-relation counts decrease from 706,632 at layer 13 to 548,056 at layer 20. Bent certification rises to 29.798927 s at layer 18 with 750,346 new relations. Detailed causal subdivision of this increase: Not measured. No claim is made that the rejected layer-19 work qualified.')
    add('M. Remesh events','Committed remesh events: 0. No rollback cavity, coupled revision, or mixed transition was committed in this task. Their production-scale performance is not qualified here. Existing fallback/transaction tests pass, but the large bent fallback stalled. Frozen gates correctly rejected the invalid nominal layer.')
    add('N. Memory','Per-layer RSS is in the ledger. Peak is the process high-water mark and can include earlier checkpoint/restart work; it is not an isolated layer allocation measurement. Capsule ordinary-run peak reached 3,709,558,784 bytes; final retained 3,450,642,432 bytes. Successful complete assembly peak 8,894,955,520 bytes. Bent rejected fallback peak 9,964,425,216 bytes, retained at interruption 9,907,290,112 bytes. Exact ownership of native/allocator/mmap pages: Not measured. Large raw payloads remain locally hash-bound rather than committed to Git.')
    add('O. Milestone restart','Exact milestone roundtrips pass at capsule 16/20, bent 10/14/18, and interacting 4. A disk-full capsule-16 partial write was recovered from saved geometry and exact re-certified missing proof deltas, followed by independent global sealing. Its operational transaction generation was reset; uninterrupted generation identity is not claimed. Schema V4ProductionFastLocalMilestone/2 streams compressed, hash-verified payloads and atomically publishes CURRENT. Original source authorities remain separate. Recovery failures and storage migration are preserved. Current mixed-topology import was not exercised by a committed remesh; a geometry mismatch rejects import after preserving the general checkpoint.')
    add('P. Complete-mesh outcomes','One new bounded complete mesh qualifies: capsule, 195,206 cells. The five complete scientific output files from the interrupted and successful publication are byte-identical; COMPLETE_RETRY_ARTIFACT_COMPARISON.json records hashes. Bent is a sealed partial shell, not a complete-domain mesh. Other case outcomes are listed above.')
    add('Q. Foundation outcomes','Not run. These are bounded analytic cases without authoritative production CFD patch/control definitions. No fake CFD domain or numerical controls were introduced. No new CFD-accuracy claim is made.')
    add('R. SF2 regression','SF2 is regression-only. Preserved sealed authority: 2,126,040 shell prisms; 56,462,864 relations; zero missing/duplicate/forbidden/unresolved/remesh; exact wall and first layer. Fresh bounded SF2 tests: 15 passed, 2 explicitly deselected full-manifest/forecast materialization tests. No fresh full SF2 run or full restart is claimed; SF2_REUSE.json binds prior evidence.')
    add('S. Determinism','Milestone signatures cover geometry, topology, degree, atlas/forecast, and compact proof state. Normal restart matches exactly. Core publication retry is byte-identical for coordinates, connectivity, quality, new certificate, and volume. Canonical live-proof streaming reproduces existing canonical bytes/digests, including nested payloads. Complete fresh layer-by-layer A/A replay was not run.')
    add('T. Tests','Final changed-code regression: 86 passed, 2 expected RuntimeWarnings from invalid-geometry rejection. Fresh bounded SF2: 15 passed, 2 deselected. Earlier focused runs are preserved and overlap these suites; they are not added into a fictitious unique total. An initial test command used a nonexistent filename and ran no tests; the corrected command passed. Generic changes: durable compressed milestones, verified current-state core handoff, authority reconstruction for unavailable receipt storage, and exact canonical proof streaming. The initial strided-search-copy hypothesis was not supported by measurement and was not adopted. A 30,000-row storage reproducer measured 1.188118 s legacy canonicalization versus 0.370891 s exact streaming; no extrapolated production saving is claimed.')
    add('U. Classification','V4ProductionScaleResumeFastPartiallyQualified. Capsule shell and complete mesh qualify; bent makes sustained progress and seals at 18. Large correction/remesh fallback remains bounded only by the stop policy, not qualified for successful completion. Remaining case limitations are explicit; this is not universal production robustness.')
    add('V. Supported claim',f"The unchanged ProductionFast science committed {len(rows)} new ordinary layers across the executed cases, with measured timing and exact final evidence. Capsule reaches all 20 requested layers and a fixed-interface bounded complete mesh. This establishes sustained ordinary-layer production progress; it does not establish successful multi-event remeshing, all four case completion, or broad CFD accuracy.")
    add('W. Recommended next task','Qualify the generic large-case correction/remesh fallback from bent layer 18, using the preserved layer-19 failed proposal. Measure and bound full-shell proposal/validation/certificate work before further broad advancement. Restore or independently reconstruct unavailable historical receipt authorities before resuming the remaining cases. Do not lower gates or retune geometry.')
    report='## Decision question\n\nUsing the qualified ProductionFast and incremental-validation methodology, can the preserved larger V4 geometries now make sustained production-scale progress without qualification-only overhead dominating runtime?\n\n'+'\n\n'.join(sections)+'\n'
    (ROOT/'report.md').write_text(report,encoding='utf-8')
    artifacts=[]
    for path in sorted(ROOT.rglob('*')):
        if path.is_file() and path.name not in ('AUTHORITY.json','SHA256SUMS.json'):
            artifacts.append(dict(path=str(path.relative_to(ROOT)),bytes=path.stat().st_size,sha256=digest(path)))
    changed=subprocess.check_output(['git','diff','HEAD','--name-only','--','research/sdf_cfd_mesher_v4']).decode().splitlines()
    created=subprocess.check_output(['git','ls-files','--others','--exclude-standard','--','research/sdf_cfd_mesher_v4/tools','research/sdf_cfd_mesher_v4/tests']).decode().splitlines()
    implementation={p:digest(Path(p)) for p in sorted(set(changed+created)) if p.endswith('.py')}
    authority=dict(schema='V4ProductionScaleResumeFastAuthority/1',classification='V4ProductionScaleResumeFastPartiallyQualified',
        initial_head=read('TASK_MANIFEST.json')['head'],report_sha256=digest(ROOT/'report.md'),cases=cases,
        execution=runtime,ordinary_layers=len(rows),complete_meshes=1,committed_remesh_events=0,
        gates_unchanged=True,v3_task_modifications=0,implementation=implementation,artifacts=artifacts)
    (ROOT/'AUTHORITY.json').write_text(json.dumps(authority,indent=2),encoding='utf-8')
    hashes={name:digest(ROOT/name) for name in ('report.md','AUTHORITY.json')}
    (ROOT/'SHA256SUMS.json').write_text(json.dumps(hashes,indent=2));print(json.dumps(hashes))


if __name__=='__main__':main()
